\therefore \quad \mathrm{m} & =\frac{\mathrm{qV}}{\mathrm{gd}}=\frac{1.6 \times 10^{-19} \times 980}{9.8 \times 10^{-2} \times 8} \\
& =2 \times 10^{-16} \mathrm{ kg}
\end{aligned}
